insert into primespaces_private.facilities(id,organization_id,name,city,address,description,category,capacity,rate_cents,approval_mode,amenities,rules,opens_at,closes_at,image_key,is_sample) values
('b1000000-0000-4000-8000-000000000001','a1000000-0000-4000-8000-000000000001','A little room for big games.','Queen Creek','Sample location · Queen Creek, AZ','A bright, full-size school gym for team practices, youth leagues and community recreation. Hardwood courts, bleachers and plenty of room to bring your team together.','Gymnasium',200,9000,'manual',array['Basketball court','Bleachers','Free parking','Accessible'],'Athletic shoes required. No food on the court. Adult supervision required for youth groups. Leave the space as you found it.','16:00','22:00','gym',true),
('b1000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000002','Gather around something good.','Gilbert','Sample location · Gilbert, AZ','An inviting church event hall for celebrations, workshops and gatherings. Flexible seating and a welcoming atmosphere make it easy to bring people together.','Event hall',120,6500,'manual',array['Tables & chairs','Kitchen access','Free parking','Accessible'],'No alcohol or smoking. Music must end by 9 PM. Kitchen use includes cleanup. Please respect neighboring services.','08:00','21:00','hall',true),
('b1000000-0000-4000-8000-000000000003','a1000000-0000-4000-8000-000000000003','A space for your next great idea.','Mesa','Sample location · Mesa, AZ','A sunny community meeting room for local groups, small workshops and working sessions. Arrive with an idea; we have the tables, Wi-Fi and whiteboard ready.','Meeting room',24,4000,'instant',array['Wi-Fi','Whiteboard','Tables & chairs','Accessible'],'Keep noise at a conversational level. No amplified music. Restore the original table layout. Maximum 24 guests.','08:00','20:00','meeting',true),
('b1000000-0000-4000-8000-000000000004','a1000000-0000-4000-8000-000000000004','Make your next moment a big one.','Scottsdale','Sample location · Scottsdale, AZ','A thoughtfully designed private event venue for presentations, creative sessions and memorable occasions. An open floor plan gives your gathering room to take shape.','Auditorium',80,12000,'manual',array['Projector','Sound system','Wi-Fi','Free parking'],'Events require facility approval. No open flames. Decorations must be freestanding. Setup and cleanup must fit within the booking.','09:00','22:00','auditorium',true),
('b1000000-0000-4000-8000-000000000005','a1000000-0000-4000-8000-000000000001','Take the team outside.','Queen Creek','Sample location · Queen Creek, AZ','An open grass field for training sessions, youth sports and outdoor community activities. Book a little fresh air and a lot of possibility.','Sports field',100,5500,'manual',array['Grass field','Free parking','Restrooms'],'Daylight activities only. No vehicles on the grass. No stakes or digging. Weather-related closures may apply.','08:00','18:00','field',true),
('b1000000-0000-4000-8000-000000000006','a1000000-0000-4000-8000-000000000001','Good things start in a classroom.','Chandler','Sample location · Chandler, AZ','A comfortable classroom for tutoring, learning clubs and small training sessions. Simple, practical and ready for your next chapter.','Classroom',30,3500,'instant',array['Wi-Fi','Whiteboard','Desks & chairs','Accessible'],'No food near classroom equipment. Minors must be supervised. Leave classroom supplies and displays in place.','16:00','21:00','classroom',true);
